#!/usr/bin/env bash
# Copies secrets whose value must match GCP into the environment's Key Vault. The value goes from
# Secret Manager to Key Vault through a pipe and is never printed or written to disk.
#
#   azure/scripts/copy-secrets.sh prod
#
# Stage needs nothing here: its secrets are generated by Terraform.
set -euo pipefail
# shellcheck source=lib.sh
. "$(dirname "$0")/lib.sh"
petfolioo_env "${1:-}"
[ "$ENV" = prod ] || { echo "only prod copies secrets from GCP" >&2; exit 2; }

GCP_ACCOUNT=petroll.site.contactus@gmail.com
KV=$(az keyvault list -g "$RG" --query "[?starts_with(name, 'kvpetfolioo')].name | [0]" -o tsv)

# Key Vault name:Secret Manager name (petroll-production). Add pairs here as secrets are added.
PAIRS="jwt-secret:jwt-secret"
for pair in $PAIRS; do
  kv_name="${pair%%:*}"; gcp_name="${pair#*:}"
  gcloud secrets versions access latest --secret="$gcp_name" --project=petroll-production --account="$GCP_ACCOUNT" |
    az keyvault secret set --vault-name "$KV" --name "$kv_name" --file /dev/stdin --encoding utf-8 -o none
  echo "==> ${kv_name} copied"
done
echo "==> Restart the API so it reads the new value: az containerapp revision restart (or roll a new image)"
